78	static uint8_t* read_all_from_file(const char* path)
79	{
80	    int fd = 0;
81	    int flen = 0;
82	    uint8_t* content = NULL;
83	
84	    fd = open(path, O_RDONLY);
85	
86	    if (fd < 0) {
87	        fprintf(stderr, "ERROR(showlogo): file :%s open failed! errno is %d\n", path, errno);
88	        return NULL;
89	    }
90	
91	    flen = lseek(fd, 0L, SEEK_END);
92	
93	    if (flen == -1) {
94	      fprintf(stderr, "ERROR(showlogo): lseek failed: %d\n", errno);
95	      close(fd);
96	      return NULL;
97	    }
98	    lseek(fd, 0L, SEEK_SET);
99	
100	    content = malloc(flen + 1);
101	
102	    DEBUGASSERT(content != NULL);
103	
104	    if (content) {
105	        read(fd, content, flen);
106	        content[flen] = 0;
107	    }
108	    close(fd);
109	    return content;
110	}
