static int compare_u32(const void *lhs, const void *rhs)
{
    uint32_t a = *(const uint32_t *)lhs;
    uint32_t b = *(const uint32_t *)rhs;

    return (a > b) - (a < b);
}

static int sample_row(enum lc3_profile_metric metric)
{
    for (int i = 0; i < LC3_PROFILE_SAMPLE_METRICS; i++)
        if (g_sample_metrics[i] == metric)
            return i;

    return -1;
}

static uint32_t percentile(const uint32_t *samples, uint32_t count,
    unsigned int percent)
{
    uint32_t sorted[LC3_PROFILE_WINDOW_FRAMES];
    uint32_t index;

    memcpy(sorted, samples, count * sizeof(*samples));
    qsort(sorted, count, sizeof(*sorted), compare_u32);

    index = (count * percent + 99) / 100 - 1;
    return sorted[index];
}

static void report_metric(const struct lc3_profile *profile,
    enum lc3_profile_metric metric)
{
    const struct lc3_profile_stats *stats = &profile->stats[metric];
    uint64_t encode_total =
        profile->stats[LC3_PROFILE_ENCODE_TOTAL].total;
    uint64_t average = stats->count ? stats->total / stats->count : 0;
    uint64_t share_bp = encode_total ?
        stats->total * 10000 / encode_total : 0;
    uint32_t minimum = stats->count ? stats->min : 0;
    uint32_t maximum = stats->count ? stats->max : 0;
    int row = sample_row(metric);

    if (row >= 0 && stats->count) {
        uint32_t sample_count = stats->count;
        uint32_t p50;
        uint32_t p95;

        if (sample_count > LC3_PROFILE_WINDOW_FRAMES)
            sample_count = LC3_PROFILE_WINDOW_FRAMES;

        p50 = percentile(profile->samples[row], sample_count, 50);
        p95 = percentile(profile->samples[row], sample_count, 95);

        syslog(LOG_EMERG,
            "LC3PROF METRIC seq=%" PRIu32 " name=%s count=%" PRIu32
            " total=%" PRIu64 " avg=%" PRIu64 " min=%" PRIu32
            " p50=%" PRIu32 " p95=%" PRIu32 " max=%" PRIu32
            " share_bp=%" PRIu64 "\n",
            profile->sequence, g_metric_names[metric], stats->count,
            stats->total, average, minimum, p50, p95, maximum, share_bp);
    } else {
        syslog(LOG_EMERG,
            "LC3PROF METRIC seq=%" PRIu32 " name=%s count=%" PRIu32
            " total=%" PRIu64 " avg=%" PRIu64 " min=%" PRIu32
            " p50=NA p95=NA max=%" PRIu32 " share_bp=%" PRIu64 "\n",
            profile->sequence, g_metric_names[metric], stats->count,
            stats->total, average, minimum, maximum, share_bp);
    }
}

static void report_window(const struct lc3_profile *profile)
{
    int dt_us = profile->dt >= 0 && profile->dt < LC3_NUM_DT ?
        g_dt_us[profile->dt] : 0;
    int srate_hz = profile->sr >= 0 && profile->sr < LC3_NUM_SRATE ?
        g_srate_hz[profile->sr] : 0;

    syslog(LOG_EMERG,
        "LC3PROF META seq=%" PRIu32 " frames=%" PRIu32
        " warmup=%d freq=%lu probe_overhead=%" PRIu32
        " timing=instrumented_inclusive sr=%d frame_us=%d nbytes=%d\n",
        profile->sequence, profile->frame_count,
        LC3_PROFILE_WARMUP_FRAMES, perf_getfreq(), profile->overhead,
        srate_hz, dt_us, profile->nbytes);

    for (int metric = 0; metric < LC3_PROFILE_METRIC_COUNT; metric++)
        report_metric(profile, metric);
}

static void reset_window(struct lc3_profile *profile)
{
    memset(profile->stats, 0, sizeof(profile->stats));
    memset(profile->current, 0, sizeof(profile->current));
    memset(profile->samples, 0, sizeof(profile->samples));
    profile->touched = 0;
    profile->frame_count = 0;
    profile->active = false;
    profile->ready = false;
}

static uint32_t elapsed_cycles(clock_t start)
{
    clock_t elapsed = perf_gettime() - start;

    return elapsed > UINT32_MAX ? UINT32_MAX : (uint32_t)elapsed;
}

void lc3_profile_init(struct lc3_profile *profile)
{
    uint32_t overhead = UINT32_MAX;

    memset(profile, 0, sizeof(*profile));

    for (int i = 0; i < 32; i++) {
        clock_t start = perf_gettime();
        uint32_t delta = elapsed_cycles(start);

        if (delta < overhead)
            overhead = delta;
    }

    profile->overhead = overhead == UINT32_MAX ? 0 : overhead;
    profile->warmup_remaining = LC3_PROFILE_WARMUP_FRAMES;
    profile->sequence = 1;
}

void lc3_profile_frame_begin(struct lc3_profile *profile,
    int dt, int sr, int nbytes)
{
    bool config_changed = profile->config_valid &&
        (profile->dt != dt || profile->sr != sr || profile->nbytes != nbytes);

    profile->active = false;

    /* Preserve a completed snapshot until the cold path reports it. */
    if (profile->ready)
        return;

    if (config_changed) {
        reset_window(profile);
        profile->warmup_remaining = LC3_PROFILE_WARMUP_FRAMES;
    }

    profile->dt = dt;
    profile->sr = sr;
    profile->nbytes = nbytes;
    profile->config_valid = true;

    memset(profile->current, 0, sizeof(profile->current));
    profile->touched = 0;

    if (profile->warmup_remaining) {
        profile->warmup_remaining--;
        return;
    }

    profile->active = true;
}

clock_t lc3_profile_start(const struct lc3_profile *profile)
{
    return profile->active ? perf_gettime() : 0;
}

void lc3_profile_stop(struct lc3_profile *profile,
    enum lc3_profile_metric metric, clock_t start)
{
    uint32_t delta;

    if (!profile->active || metric < 0 || metric >= LC3_PROFILE_METRIC_COUNT)
        return;

    delta = elapsed_cycles(start);
    delta = delta > profile->overhead ? delta - profile->overhead : 0;

    if (UINT32_MAX - profile->current[metric] < delta)
        profile->current[metric] = UINT32_MAX;
    else
        profile->current[metric] += delta;

    profile->touched |= 1u << metric;
}

void lc3_profile_frame_end(struct lc3_profile *profile)
{
    if (!profile->active)
        return;

    for (int metric = 0; metric < LC3_PROFILE_METRIC_COUNT; metric++) {
        struct lc3_profile_stats *stats;
        uint32_t value;
        int row;

        if (!(profile->touched & (1u << metric)))
            continue;

        stats = &profile->stats[metric];
        value = profile->current[metric];

        if (!stats->count || value < stats->min)
            stats->min = value;
        if (!stats->count || value > stats->max)
            stats->max = value;

        stats->total += value;
        stats->count++;

        row = sample_row(metric);
        if (row >= 0 && stats->count <= LC3_PROFILE_WINDOW_FRAMES)
            profile->samples[row][stats->count - 1] = value;
    }

    profile->frame_count++;
    profile->active = false;

    if (profile->frame_count == LC3_PROFILE_WINDOW_FRAMES)
        profile->ready = true;
}

void lc3_profile_report(struct lc3_profile *profile)
{
    if (!profile->frame_count)
        return;

    report_window(profile);
    profile->sequence++;
    reset_window(profile);
}

