    uint16_t bitrate_100bps;
    uint16_t channels;
    uint16_t frame_10us;
    uint16_t epmode;
    uint16_t nsamples_low;
    uint16_t nsamples_high;
};

static void usage(const char *prog)
{
    printf("Usage: %s [-i input.sw] [-o output.lc3] [-h]\n", prog);
    exit(EXIT_FAILURE);
}

/* FNV-1a 64-bit hash, used to fingerprint the encoded bitstream so that
 * every MVE variant can be checked byte-for-byte against the baseline. */
static uint64_t fnv1a_update(uint64_t hash, const void *data, size_t len)
{
    const uint8_t *p = data;

    for (size_t i = 0; i < len; i++) {
        hash ^= p[i];
        hash *= 0x100000001b3ULL;
    }

    return hash;
}

int main(int argc, char *argv[])
{
    const char *in_path = DEFAULT_IN;
    const char *out_path = DEFAULT_OUT;
    int ch;

    while ((ch = getopt(argc, argv, "hi:o:")) != -1) {
        switch (ch) {
        case 'h':
            usage(argv[0]);
            break;
        case 'i':
            in_path = optarg;
            break;
        case 'o':
            out_path = optarg;
            break;
        default:
            usage(argv[0]);
        }
    }

    /* --- Open input (raw S16 LE mono) --- */
    int fd_in = open(in_path, O_RDONLY);
    if (fd_in < 0) {
        fprintf(stderr, "ERROR(lc3bench): open %s failed, errno %d\n",
                in_path, errno);
        return EXIT_FAILURE;
    }

    off_t file_size = lseek(fd_in, 0, SEEK_END);
    if (file_size < 0) {
        fprintf(stderr, "ERROR(lc3bench): lseek failed, errno %d\n", errno);
        close(fd_in);
        return EXIT_FAILURE;
    }
    lseek(fd_in, 0, SEEK_SET);

    int nsamples = (int)(file_size / sizeof(int16_t));

    /* --- Setup encoder --- */
    int frame_samples = lc3_frame_samples(LC3_DT_US, LC3_SR_HZ);
    int delay = lc3_delay_samples(LC3_DT_US, LC3_SR_HZ);
    int block_bytes = lc3_frame_block_bytes(LC3_DT_US, 1, LC3_BITRATE);
    int nframes = (nsamples + delay + frame_samples - 1) / frame_samples;

    unsigned enc_size = lc3_encoder_size(LC3_DT_US, LC3_SR_HZ);
    void *enc_mem = malloc(enc_size);
    lc3_encoder_t enc = lc3_setup_encoder(LC3_DT_US, LC3_SR_HZ, 0, enc_mem);

    if (!enc) {
        fprintf(stderr, "ERROR(lc3bench): setup encoder failed\n");
        free(enc_mem);
        close(fd_in);
        return EXIT_FAILURE;
    }

    /* --- Open output (LC3 binary container) --- */
    int fd_out = open(out_path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd_out < 0) {
        fprintf(stderr, "ERROR(lc3bench): open %s failed, errno %d\n",
                out_path, errno);
        free(enc_mem);
        close(fd_in);
        return EXIT_FAILURE;
    }

    struct lc3bin_header hdr = {
        .file_id = LC3_FILE_ID,
        .header_size = sizeof(hdr),
        .srate_100hz = LC3_SR_HZ / 100,
        .bitrate_100bps = LC3_BITRATE / 100,
        .channels = 1,
        .frame_10us = LC3_DT_US / 10,
        .epmode = 0,
        .nsamples_low = nsamples & 0xffff,
        .nsamples_high = nsamples >> 16,
    };

    uint64_t hash = fnv1a_update(0xcbf29ce484222325ULL, &hdr, sizeof(hdr));
    write(fd_out, &hdr, sizeof(hdr));

    /* --- Encode loop --- */
    int16_t pcm[LC3_MAX_FRAME_SAMPLES];
    uint8_t out[LC3_MAX_FRAME_BYTES];

    for (int i = 0; i < nframes; i++) {
        int done = i * frame_samples;
        int remain = nsamples - done;
        int nread = remain > 0 ?
            (remain < frame_samples ? remain : frame_samples) : 0;

        if (nread > 0 && read(fd_in, pcm, nread * sizeof(int16_t))
                != (ssize_t)(nread * sizeof(int16_t))) {
            fprintf(stderr, "ERROR(lc3bench): short read at frame %d\n", i);
            free(enc_mem);
            close(fd_in);
            close(fd_out);
            return EXIT_FAILURE;
        }

        if (nread < frame_samples)
            memset(pcm + nread, 0,
                   (frame_samples - nread) * sizeof(int16_t));

        if (lc3_encode(enc, LC3_PCM_FORMAT_S16, pcm, 1, block_bytes, out) != 0) {
            fprintf(stderr, "ERROR(lc3bench): encode frame %d failed\n", i);
            free(enc_mem);
            close(fd_in);
            close(fd_out);
            return EXIT_FAILURE;
        }

        uint16_t len = block_bytes;
        hash = fnv1a_update(hash, &len, sizeof(len));
        hash = fnv1a_update(hash, out, block_bytes);
        write(fd_out, &len, sizeof(len));
        write(fd_out, out, block_bytes);
    }

    /* --- Report --- */
    off_t out_size = lseek(fd_out, 0, SEEK_END);
    printf("LC3BENCH RESULT frames=%d nsamples=%d out_size=%lld "
           "checksum=%016" PRIx64 "\n",
           nframes, nsamples, (long long)out_size, hash);

#ifdef CONFIG_LIB_LC3_PROFILE
    lc3_encoder_profile_report(enc);
#endif

    free(enc_mem);
    close(fd_in);
    close(fd_out);

    return EXIT_SUCCESS;
}

