155	static void reset_window(struct lc3_profile *profile)
156	{
157	    memset(profile->stats, 0, sizeof(profile->stats));
158	    memset(profile->current, 0, sizeof(profile->current));
159	    memset(profile->samples, 0, sizeof(profile->samples));
160	    profile->touched = 0;
