173	void lc3_profile_init(struct lc3_profile *profile)
174	{
175	    uint32_t overhead = UINT32_MAX;
176	
177	    memset(profile, 0, sizeof(*profile));
178	
179	    for (int i = 0; i < 32; i++) {
180	        clock_t start = perf_gettime();
181	        uint32_t delta = elapsed_cycles(start);
182	
183	        if (delta < overhead)
184	            overhead = delta;
185	    }
186	
187	    profile->overhead = overhead == UINT32_MAX ? 0 : overhead;
188	    profile->warmup_remaining = LC3_PROFILE_WARMUP_FRAMES;
189	    profile->sequence = 1;
190	}
