192	void lc3_profile_frame_begin(struct lc3_profile *profile,
193	    int dt, int sr, int nbytes)
194	{
195	    bool config_changed = profile->config_valid &&
196	        (profile->dt != dt || profile->sr != sr || profile->nbytes != nbytes);
197	
198	    profile->active = false;
199	
200	    /* Preserve a completed snapshot until the cold path reports it. */
201	    if (profile->ready)
202	        return;
203	
204	    if (config_changed) {
205	        reset_window(profile);
206	        profile->warmup_remaining = LC3_PROFILE_WARMUP_FRAMES;
207	    }
208	
209	    profile->dt = dt;
210	    profile->sr = sr;
211	    profile->nbytes = nbytes;
212	    profile->config_valid = true;
213	
214	    memset(profile->current, 0, sizeof(profile->current));
215	    profile->touched = 0;
216	
217	    if (profile->warmup_remaining) {
218	        profile->warmup_remaining--;
219	        return;
220	    }
221	
222	    profile->active = true;
223	}
