230	void lc3_profile_stop(struct lc3_profile *profile,
231	    enum lc3_profile_metric metric, clock_t start)
232	{
233	    uint32_t delta;
234	
235	    if (!profile->active || metric < 0 || metric >= LC3_PROFILE_METRIC_COUNT)
236	        return;
237	
238	    delta = elapsed_cycles(start);
239	    delta = delta > profile->overhead ? delta - profile->overhead : 0;
240	
241	    if (UINT32_MAX - profile->current[metric] < delta)
242	        profile->current[metric] = UINT32_MAX;
243	    else
244	        profile->current[metric] += delta;
245	
246	    profile->touched |= 1u << metric;
247	}
